class Solution {
public:
    int minTravelTime(int l,int n,int k,vector<int>& position,vector<int>& time) {
        const int INF=1000000000;
        vector<int> pref(n+1);
        for(int i=0;i<n;++i) pref[i+1]=pref[i]+time[i];
        // dp[previous kept sign][current kept sign][merges so far]
        vector<vector<vector<int>>> dp(n,vector<vector<int>>(n,vector<int>(k+1,INF)));
        for(int j=1;j<n;++j) if(j-1<=k)
            dp[0][j][j-1]=(position[j]-position[0])*time[0];
        for(int a=0;a<n;++a) for(int b=a+1;b<n;++b)
            for(int used=0;used<=k;++used) if(dp[a][b][used]<INF) {
                for(int c=b+1;c<n;++c) {
                    int extra=c-b-1;
                    if(used+extra>k) break;
                    int rate=pref[b+1]-pref[a+1];
                    int cost=(position[c]-position[b])*rate;
                    dp[b][c][used+extra]=min(dp[b][c][used+extra],dp[a][b][used]+cost);
                }
            }
        int ans=INF;
        for(int a=0;a<n-1;++a) ans=min(ans,dp[a][n-1][k]);
        return ans;
    }
};
